// Retrieve all incoming items from the Webhook
const items = $input.all();

const validatedItems = items.map(item => {

  // Extract the body
  const data = item.json.body || {};

  let isValid = true;
  let errors = [];

  // 1. Check 'name' (required)
  if (!data.name || String(data.name).trim() === '') {
    isValid = false;
    errors.push("Field 'name' is required.");
  }

  // 2. Check 'email' (required + valid format)
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

  if (!data.email || String(data.email).trim() === '') {
    isValid = false;
    errors.push("Field 'email' is required.");
  } else if (!emailRegex.test(data.email)) {
    isValid = false;
    errors.push("Invalid 'email' format.");
  }

  // 3. Check 'company' (required)
  if (!data.company || String(data.company).trim() === '') {
    isValid = false;
    errors.push("Field 'company' is required.");
  }

  // 4. Check 'budget' (OPTIONAL)
  let budgetVal = data.budget;

  // Missing budget = valid
  if (
    budgetVal === null ||
    budgetVal === undefined ||
    String(budgetVal).trim() === ""
  ) {

    // Normalise the value
    data.budget = null;

  } else {

    const budgetAsNumber = Number(budgetVal);

    // Budget present: must be a number >= 0
    if (isNaN(budgetAsNumber) || budgetAsNumber < 0) {

      isValid = false;

      errors.push(
        "Field 'budget' must be a number greater than or equal to 0."
      );

    } else {

      // Convert to a true number
      data.budget = budgetAsNumber;
    }
  }

  // 5. Check 'message' (required)
  if (!data.message || String(data.message).trim() === '') {
    isValid = false;
    errors.push("Field 'message' is required.");
  }

  // Return cleaned data + validation result
  return {
    json: {
      ...data,

      validation: {
        isValid: isValid,
        errors: errors
      }
    }
  };
});

return validatedItems;

const item = $input.first();

try {
  // Access the nested arrays using [0] for 'output' and [0] for 'content'
  let rawText = item.json.output[0].content[0].text;

  // Remove Markdown code fences if present (```json ... ```)
  if (rawText.includes('```json')) {
    rawText = rawText.split('```json')[1].split('```')[0];
  } else if (rawText.includes('```')) {
    rawText = rawText.split('```')[1].split('```')[0];
  }

  // Trim any remaining whitespace or newlines
  rawText = rawText.trim();

  // Parse the cleaned string into a proper JSON object
  const parsedData = JSON.parse(rawText);

  // Force 'business_needs' to be an array of strings
  if (parsedData.business_needs && typeof parsedData.business_needs === 'string') {
    parsedData.business_needs = [parsedData.business_needs];
  } else if (!parsedData.business_needs) {
    parsedData.business_needs = [];
  }

  // Return the final cleaned object
  return [{ json: parsedData }];

} catch (error) {
  // On failure, return the error and where it occurred
  return [{ 
    json: { 
      error: "Failed to decode LLM JSON", 
      message: error.message
    } 
  }];
}

// Helper: strip currency symbols and convert to integer
function parseBudget(value) {
  if (value === null || value === undefined || value === 'unknown' || value === '') {
    return null;
  }
  // Already a number — return as-is
  if (typeof value === 'number') return value;

  // Remove € and spaces, then strip thousand-separator dots
  let cleaned = value.toString().replace(/[€\s]/g, '').replace(/\./g, '');
  let num = parseInt(cleaned, 10);

  return isNaN(num) ? null : num;
}

// Iterate over all incoming records
for (const item of $input.all()) {
  let score = 0;

  // 1. Budget score
  const rawBudget = item.json.estimated_budget;
  const budget = parseBudget(rawBudget);

  if (budget === null) {
    score += 0;
  } else if (budget >= 5000) {
    score += 40;
  } else if (budget >= 3000 && budget <= 4999) {
    score += 30;
  } else if (budget >= 1000 && budget <= 2999) {
    score += 20;
  } else if (budget < 1000) {
    score += 10;
  }

  // 2. Urgency score
  const urgency = (item.json.urgency || '').toLowerCase().trim();
  if (urgency === 'high') {
    score += 30;
  } else if (urgency === 'medium') {
    score += 20;
  } else if (urgency === 'low') {
    score += 10;
  } else {
    score += 0; // unknown
  }

  // 3. Determine priority from total score
  let priority = 'LOW';
  if (score >= 60) {
    priority = 'HIGH';
  } else if (score >= 30 && score <= 59) {
    priority = 'MEDIUM';
  }

  // Attach computed fields to the JSON object
  item.json.total_score = score;
  item.json.final_priority = priority;
}

// Return all items to the next n8n node
return $input.all();

